using System;
using System.IO;
using System.IO.MemoryMappedFiles;
using System.Collections.Generic;
using LibOrbisPkg.PKG;
using LibOrbisPkg.PFS;
class KaliwPkg {
 static string Safe(string root,string name){name=name.Replace('\\','/').TrimStart('/');var bits=name.Split('/');foreach(var bit in bits)if(bit.Length==0||bit=="."||bit==".."||bit.IndexOfAny(Path.GetInvalidFileNameChars())>=0||bit.EndsWith(" ")||bit.EndsWith("."))throw new Exception("Unsafe package path");foreach(var bit in bits)if(System.Text.RegularExpressions.Regex.IsMatch(bit,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new Exception("Reserved package path");string target=Path.GetFullPath(Path.Combine(root,Path.Combine(bits)));if(!target.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Package path escapes destination");return target;}
 static int Main(string[] args){try{if(args.Length!=3||(args[0]!="metadata"&&args[0]!="extract"))throw new Exception("Usage: kaliw-pkg metadata|extract input.pkg output-directory");string output=Path.GetFullPath(args[2]).TrimEnd(Path.DirectorySeparatorChar);Directory.CreateDirectory(output);using(var mm=MemoryMappedFile.CreateFromFile(args[1],FileMode.Open,null,0,MemoryMappedFileAccess.Read)){Pkg pkg;using(var stream=mm.CreateViewStream(0,0,MemoryMappedFileAccess.Read)){var reader=new PkgReader(stream);var header=reader.ReadHeader();if(header.entry_count>10000||header.entry_table_offset+(long)header.entry_count*32>stream.Length)throw new Exception("Invalid PKG entry table");pkg=reader.ReadPkg();foreach(var entry in pkg.Metas.Metas)if(entry.DataSize>104857600||entry.DataOffset+(long)entry.DataSize>stream.Length)throw new Exception("Invalid PKG entry size");var meta=pkg.ParamSfo.meta;if(meta.DataSize>1048576)throw new Exception("SFO too large");stream.Position=meta.DataOffset;var data=new byte[meta.DataSize];if(stream.Read(data,0,data.Length)!=data.Length)throw new Exception("Truncated SFO");File.WriteAllBytes(Path.Combine(output,"param.sfo"),data);}
 if(args[0]=="metadata")return 0;
 using(var view=mm.CreateViewAccessor((long)pkg.Header.pfs_image_offset,(long)pkg.Header.pfs_image_size,MemoryMappedFileAccess.Read)){var outer=new PfsReader(view,pkg.Header.pfs_flags,pkg.GetEkpfs());var inner=new PfsReader(new PFSCReader(outer.GetFile("pfs_image.dat").GetView()));var files=new List<PfsReader.File>();var targets=new List<string>();var unique=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;foreach(var file in inner.GetAllFiles()){if(files.Count>=100000||file.size<0||file.size>68719476736L||(total+=file.size)>137438953472L)throw new Exception("Package extraction limits exceeded");var target=Safe(output,file.FullName);if(!unique.Add(target))throw new Exception("Duplicate package path");files.Add(file);targets.Add(target);}if(new DriveInfo(Path.GetPathRoot(output)).AvailableFreeSpace<total+16777216)throw new Exception("Insufficient disk space");long done=0;var buffer=new byte[1048576];for(int i=0;i<files.Count;i++){Directory.CreateDirectory(Path.GetDirectoryName(targets[i]));using(var dst=new FileStream(targets[i],FileMode.CreateNew,FileAccess.Write)){var src=files[i].GetView();long offset=0;while(offset<files[i].size){int n=(int)Math.Min(buffer.Length,files[i].size-offset);src.Read(offset,buffer,0,n);dst.Write(buffer,0,n);offset+=n;done+=n;Console.WriteLine("PROGRESS "+done+" "+total);}}}Console.WriteLine("DONE "+files.Count);}}
 return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}
